    /** Maps provider ids (and RelayRoom's upstream names) onto a logo. */
    fun logoKey(providerId: String): String = when (val id = providerId.lowercase()) {
        "gemini", "google-vertex", "vertex" -> "google"
        "github-copilot", "githubcopilot" -> "copilot"
        "grok", "x-ai" -> "xai"
        "opencode-go", "opencode-zen" -> "opencode"
        "vercel-ai-gateway" -> "vercel"
        else -> id
    }

    private class LogoScope(private val builder: ImageVector.Builder) {
        fun path(fill: Color, alpha: Float, evenOdd: Boolean, d: String) {
            builder.addPath(
                pathData = addPathNodes(d),
                fill = SolidColor(fill),
                fillAlpha = alpha,
                pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero
            )
        }
    }

    private inline fun logo(name: String, block: LogoScope.() -> Unit): ImageVector {
        val builder = ImageVector.Builder(
            name = "provider_$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f
        )
        LogoScope(builder).block()
        return builder.build()
    }
